sys_ux_client_script.script:
var StudentLoginUtils = Class.create();
StudentLoginUtils.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    validateUser: function() {

        var username = this.getParameter('sysparm_username');  // admin username or ignored for student/alumni
        var password = this.getParameter('sysparm_password');
        var role = this.getParameter('sysparm_role');
        var rollno = this.getParameter('sysparm_rollno');      // student roll no or alumni id

        if (password != '1234') {
            return 'invalid';
        }

        // Student login: check roll number
        if (role == 'student') {
            var grStudent = new GlideRecord('student');  // replace with your table name
            grStudent.addQuery('number', rollno);      // username field is roll number
            grStudent.query();
            if (grStudent.next()) {
                return 'valid_student';
            }
        }

        // Alumni login: check alumniid
        if (role == 'alumni') {
            var grAlumni = new GlideRecord('alumni');    // replace with your alumni table name
            grAlumni.addQuery('alumniid', rollno);      // alumniid field
            grAlumni.query();
            if (grAlumni.next()) {
                return 'valid_alumni';
            }
        }

        // Admin login
        if (role == 'admin') {
            if (username == 'admin') {
                return 'valid_admin';
            }
        }

        return 'invalid';
    }

});
